/** 되묻기 답변 음성의 전사 초안 API입니다. */
package com.dandimate.durooduroo.askback.controller;
import com.dandimate.durooduroo.ai.service.OpenAiTranscriptionService; import com.dandimate.durooduroo.askback.repository.AskbackRepository; import com.dandimate.durooduroo.common.api.ApiResponse; import com.dandimate.durooduroo.common.auth.MemberTokenResolver; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.repository.MemberRepository; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.time.LocalDateTime; import java.util.*;
@RestController public class AskbackTranscriptionController {private final AskbackRepository askbacks;private final MemberRepository members;private final OpenAiTranscriptionService stt;public AskbackTranscriptionController(AskbackRepository a,MemberRepository m,OpenAiTranscriptionService s){askbacks=a;members=m;stt=s;}@PostMapping(value="/api/v1/askbacks/{askbackId}/transcriptions",consumes="multipart/form-data")public ApiResponse<?> transcribe(@PathVariable String askbackId,@RequestHeader(required=false) String authorization,@RequestParam(required=false) String memberToken,@RequestPart MultipartFile file){var a=askbacks.findById(askbackId).orElseThrow(()->new BusinessException("ASKBACK_NOT_FOUND","되묻기가 없습니다."));String token=MemberTokenResolver.resolve(authorization,memberToken);var me=members.findByRoomIdAndMemberToken(a.getRoomId(),token).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","대상 참여자만 사용할 수 있습니다."));if(!me.getId().equals(a.getTargetMemberId()))throw new BusinessException("FORBIDDEN","대상 참여자만 사용할 수 있습니다.");if(file.isEmpty())throw new BusinessException("INVALID_AUDIO","음성 파일이 비어 있습니다.");return ApiResponse.success(Map.of("transcriptionId",UUID.randomUUID().toString(),"audioAssetId",UUID.randomUUID().toString(),"transcript",stt.transcribe(file),"detectedLanguages",List.of("ko"),"expiresAt",LocalDateTime.now().plusHours(24)));}}
